export const ORIGINAL_ANSWERS = "every projectile scenario: flight = time of flight, until it lands; top = greatest height above the GROUND (not above the launch); rise = greatest height above the point it was launched from; tTop = time to the greatest height; range = horizontal distance to where it lands; vLand = speed as it lands; u = speed of projection; vTop = speed at its highest point (the top of its path); theta = angle of projection; above = how long it spends above the height asked about (more than so many metres up)\nroad: s = the distance between the two points; u = the velocity at the first point; v = the velocity at the second point; a = the acceleration; t = the time between the two points; tMid = the time from the first point to the mid-point (or the mark); vMid = the speed at the mid-point (or the mark); tRest = when it is (instantaneously) at rest, before it turns back; path = the total distance travelled, counting the way back (not the displacement); sAt = how far from the first point it is at the time asked (after so many seconds); vAt = its velocity at the time asked (after so many seconds)";
